/* TodoMVC Vanilla JS */

(function () {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-vanillajs';

  // ----- Model -----

  var todos = loadTodos();

  function loadTodos() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      return [];
    }
  }

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function generateId() {
    return Date.now() + Math.random();
  }

  // ----- Helpers -----

  // Inject CSS for editing state: hide the toggle checkbox when editing
  var styleEl = document.createElement('style');
  styleEl.textContent = '.todo-list li.editing .toggle { display: none; }';
  document.head.appendChild(styleEl);

  function qs(sel, ctx) {
    return (ctx || document).querySelector(sel);
  }

  function qsa(sel, ctx) {
    return (ctx || document).querySelectorAll(sel);
  }

  // ----- View -----

  var todoList = qs('.todo-list');
  var newTodo = qs('.new-todo');
  var main = qs('.main');
  var footer = qs('.footer');
  var toggleAll = qs('#toggle-all');
  var todoCount = qs('.todo-count');
  var clearCompleted = qs('.clear-completed');
  var filters = qsa('.filters a');

  var currentFilter = 'all';

  function getFilteredTodos() {
    switch (currentFilter) {
      case 'active': return todos.filter(function (t) { return !t.completed; });
      case 'completed': return todos.filter(function (t) { return t.completed; });
      default: return todos;
    }
  }

  function getActiveCount() {
    return todos.filter(function (t) { return !t.completed; }).length;
  }

  function getCompletedCount() {
    return todos.filter(function (t) { return t.completed; }).length;
  }

  /**
   * @planks("I click the toggle for {string}")
   * @planks("I click {string}")
   * @planks("I click the {string} filter link")
   * @planks("the route is {string}")
   * @planks("I type {string} into {string}")
   * @planks("I press Enter")
   * @planks("I change the edit field to {string}")
   * @planks("I press Enter in the edit field")
   * @planks("the edit field loses focus")
   * @planks("I press Escape in the edit field")
   * @planks("the app is reloaded")
   */
  function render() {
    var filtered = getFilteredTodos();
    var activeCount = getActiveCount();
    var completedCount = getCompletedCount();

    // Build a map of existing <li> elements by data-id
    var existingItems = {};
    var children = todoList.children;
    for (var i = 0; i < children.length; i++) {
      var li = children[i];
      existingItems[li.dataset.id] = li;
    }

    // Render list items: update existing elements in place, create new ones
    var fragment = document.createDocumentFragment();
    filtered.forEach(function (todo) {
      var id = todo.id;
      var li = existingItems[id];
      if (li) {
        // Update existing element in place — preserves DOM reference
        li.className = todo.completed ? 'completed' : '';
        var toggle = li.querySelector('.toggle');
        toggle.checked = todo.completed;
        var label = li.querySelector('label');
        label.textContent = todo.title;
        var edit = li.querySelector('.edit');
        edit.value = todo.title;
        fragment.appendChild(li);
        delete existingItems[id];
      } else {
        // Create new element
        var li = document.createElement('li');
        li.className = todo.completed ? 'completed' : '';
        li.dataset.id = id;
        li.innerHTML =
          '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
          '</div>' +
          '<input class="edit" value="' + escapeHtml(todo.title) + '">';
        fragment.appendChild(li);
      }
    });

    // Remove leftover items that are no longer in the filtered list
    for (var id in existingItems) {
      existingItems[id].remove();
    }

    // Replace the list content
    todoList.innerHTML = '';
    todoList.appendChild(fragment);

    // Main and footer visibility
    var hasTodos = todos.length > 0;
    main.style.display = hasTodos ? 'block' : 'none';
    footer.style.display = hasTodos ? 'block' : 'none';

    // Toggle all
    toggleAll.checked = activeCount === 0 && todos.length > 0;

    // Counter
    var count = activeCount;
    var word = count === 1 ? 'item' : 'items';
    todoCount.innerHTML = '<strong>' + count + '</strong> ' + word + ' left';

    // Clear completed
    clearCompleted.style.display = completedCount > 0 ? 'block' : 'none';

    // Filter links
    qsa('.filters a').forEach(function (a) {
      var href = a.getAttribute('href');
      var isSelected = false;
      if (currentFilter === 'all' && href === '#/') isSelected = true;
      if (currentFilter === 'active' && href === '#/active') isSelected = true;
      if (currentFilter === 'completed' && href === '#/completed') isSelected = true;
      a.classList.toggle('selected', isSelected);
    });
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(str));
    return div.innerHTML;
  }

  // ----- Controller -----

  function addTodo(title) {
    title = title.trim();
    if (!title) return;
    todos.push({ id: generateId(), title: title, completed: false });
    saveTodos();
    render();
  }

  function removeTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    saveTodos();
    render();
  }

  function toggleTodo(id) {
    todos = todos.map(function (t) {
      if (t.id === id) t.completed = !t.completed;
      return t;
    });
    saveTodos();
    render();
  }

  function toggleAllTodos(checked) {
    todos = todos.map(function (t) {
      t.completed = checked;
      return t;
    });
    saveTodos();
    render();
  }

  function updateTodo(id, title) {
    title = title.trim();
    if (!title) {
      removeTodo(id);
      return;
    }
    todos = todos.map(function (t) {
      if (t.id === id) t.title = title;
      return t;
    });
    saveTodos();
    render();
  }

  function clearCompletedTodos() {
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos();
    render();
  }

  function setFilter(filter) {
    currentFilter = filter;
    render();
  }

  // ----- Event Handlers -----

  newTodo.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodo.value);
      newTodo.value = '';
    }
  });

  todoList.addEventListener('change', function (e) {
    var toggle = e.target.closest('.toggle');
    if (toggle) {
      var li = toggle.closest('li');
      toggleTodo(parseFloat(li.dataset.id));
    }
  });

  todoList.addEventListener('click', function (e) {
    var destroy = e.target.closest('.destroy');
    if (destroy) {
      var li = destroy.closest('li');
      removeTodo(parseFloat(li.dataset.id));
    }
  });

  todoList.addEventListener('dblclick', function (e) {
    var label = e.target.closest('label');
    if (label) {
      var li = label.closest('li');
      li.classList.add('editing');
      var editInput = li.querySelector('.edit');
      editInput.value = li.querySelector('label').textContent;
      editInput.focus();
      editInput.selectionStart = editInput.selectionEnd = editInput.value.length;
    }
  });

  todoList.addEventListener('keydown', function (e) {
    var editInput = e.target.closest('.edit');
    if (!editInput) return;
    var li = editInput.closest('li');
    var id = parseFloat(li.dataset.id);

    if (e.keyCode === ENTER_KEY) {
      e.preventDefault();
      updateTodo(id, editInput.value);
      li.classList.remove('editing');
    } else if (e.keyCode === ESCAPE_KEY) {
      e.preventDefault();
      li.classList.remove('editing');
      var original = li.querySelector('label').textContent;
      editInput.value = original;
    }
  });

  todoList.addEventListener('blur', function (e) {
    var editInput = e.target.closest('.edit');
    if (!editInput) return;
    var li = editInput.closest('li');
    if (li.classList.contains('editing')) {
      var id = parseFloat(li.dataset.id);
      updateTodo(id, editInput.value);
      li.classList.remove('editing');
    }
  }, true);

  toggleAll.addEventListener('change', function (e) {
    toggleAllTodos(toggleAll.checked);
  });

  clearCompleted.addEventListener('click', function () {
    clearCompletedTodos();
  });

  // ----- Routing -----

  function handleHashChange() {
    var hash = window.location.hash || '#/';
    switch (hash) {
      case '#/active': setFilter('active'); break;
      case '#/completed': setFilter('completed'); break;
      default: setFilter('all'); break;
    }
  }

  window.addEventListener('hashchange', handleHashChange);
  handleHashChange();

  // Initial render
  render();
})();

const { Given, When, Then, Before } = require('@cucumber/cucumber');
const assert = require('node:assert');

/**
 * @planks("the app is loaded")
 */
Given('the app is loaded', function () {
  // The world.js Before hook already loads the app.
  // This step exists as a readable Background step.
  assert.ok(this.document, 'app should be loaded');
});

/**
 * @planks("there are no todos")
 */
Given('there are no todos', function () {
  this.seedApp('todos-vanillajs', []);
});

/**
 * @planks("the todo list has items:")
 */
Given('the todo list has items:', function (table) {
  const items = table.hashes().map(function (row, i) {
    return { id: Date.now() + i, title: row.title, completed: row.completed === 'true' };
  });
  this.seedApp('todos-vanillajs', items);
});

/**
 * @planks("the todo list has item {string}")
 */
Given('the todo list has item {string}', function (title) {
  this.seedApp('todos-vanillajs', [{ id: Date.now(), title: title, completed: false }]);
});

/**
 * @planks("the todo list has item {string} completed")
 */
Given('the todo list has item {string} completed', function (title) {
  this.seedApp('todos-vanillajs', [{ id: Date.now(), title: title, completed: true }]);
});

// ── When steps ──────────────────────────────────────────────────────

/**
 * @planks("I capture the reference to the item {string}")
 */
When('I capture the reference to the item {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  let found = false;
  items.forEach(function (li) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) {
      this.capturedElement = li;
      found = true;
    }
  }.bind(this));
  assert.ok(found, 'item should exist: ' + title);
});

/**
 * @planks("I type {string} into {string}")
 */
When('I type {string} into {string}', function (text, selector) {
  const el = this.document.querySelector(selector);
  assert.ok(el, 'element should exist: ' + selector);
  el.value = text;
});

/**
 * @planks("I press Enter")
 */
When('I press Enter', function () {
  const el = this.document.querySelector('.new-todo');
  assert.ok(el, 'new-todo input should exist');
  const event = new this.window.KeyboardEvent('keydown', { keyCode: 13, key: 'Enter', bubbles: true });
  el.dispatchEvent(event);
});

/**
 * @planks("I click {string}")
 */
When('I click {string}', function (selector) {
  const el = this.document.querySelector(selector);
  assert.ok(el, 'element should exist: ' + selector);
  el.click();
});

/**
 * @planks("I click the toggle for {string}")
 */
When('I click the toggle for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  let found = false;
  items.forEach(function (li) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) {
      const toggle = li.querySelector('.toggle');
      if (toggle) { toggle.click(); found = true; }
    }
  });
  assert.ok(found, 'toggle should exist for: ' + title);
});

/**
 * @planks("I double-click the label for {string}")
 */
When('I double-click the label for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  let found = false;
  items.forEach(function (li) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) {
      const event = new this.window.MouseEvent('dblclick', { bubbles: true });
      label.dispatchEvent(event);
      found = true;
    }
  }.bind(this));
  assert.ok(found, 'label should exist for: ' + title);
});

/**
 * @planks("I change the edit field to {string}")
 */
When('I change the edit field to {string}', function (value) {
  const edit = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(edit, 'edit field should be visible');
  edit.value = value;
});

/**
 * @planks("I press Enter in the edit field")
 */
When('I press Enter in the edit field', function () {
  const edit = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(edit, 'edit field should be visible');
  const event = new this.window.KeyboardEvent('keydown', { keyCode: 13, key: 'Enter', bubbles: true });
  edit.dispatchEvent(event);
});

/**
 * @planks("the edit field loses focus")
 */
When('the edit field loses focus', function () {
  const edit = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(edit, 'edit field should be visible');
  const event = new this.window.FocusEvent('blur', { bubbles: true });
  edit.dispatchEvent(event);
});

/**
 * @planks("I press Escape in the edit field")
 */
When('I press Escape in the edit field', function () {
  const edit = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(edit, 'edit field should be visible');
  const event = new this.window.KeyboardEvent('keydown', { keyCode: 27, key: 'Escape', bubbles: true });
  edit.dispatchEvent(event);
});

/**
 * @planks("the app is reloaded")
 */
When('the app is reloaded', function () {
  // Preserve current localStorage data and hash
  const todoData = this.localStorage.getItem('todos-vanillajs');
  const currentHash = this.window.location.hash || '#/';
  if (todoData !== null) {
    const items = JSON.parse(todoData);
    this.seedApp('todos-vanillajs', items, currentHash);
  } else {
    this.disposeApp();
    this.loadApp();
  }
});

/**
 * @planks("the route is {string}")
 */
const { defineStep } = require('@cucumber/cucumber');
defineStep('the route is {string}', function (hash) {
  if (this.window.location.hash !== hash) {
    this.navigate(hash);
  }
  assert.strictEqual(this.window.location.hash, hash, 'route should be ' + hash);
});

/**
 * @planks("I click the {string} filter link")
 */
When('I click the {string} filter link', function (filterName) {
  const links = this.document.querySelectorAll('.filters a');
  let found = false;
  links.forEach(function (a) {
    if (a.textContent.trim() === filterName) {
      a.click();
      found = true;
    }
  });
  assert.ok(found, 'filter link should exist: ' + filterName);
});

// ── Then steps ──────────────────────────────────────────────────────

/**
 * @planks("{string} is not visible")
 */
Then('{string} is not visible', function (selector) {
  const el = this.document.querySelector(selector);
  // Check style.display or absence
  if (!el) return; // not in DOM = not visible
  const style = this.window.getComputedStyle(el);
  assert.strictEqual(style.display, 'none', selector + ' should not be visible');
});

/**
 * @planks("{string} is visible")
 */
Then('{string} is visible', function (selector) {
  const el = this.document.querySelector(selector);
  assert.ok(el, 'element should exist: ' + selector);
  const style = this.window.getComputedStyle(el);
  assert.notStrictEqual(style.display, 'none', selector + ' should be visible');
});

/**
 * @planks("the todo list contains {int} item")
 */
Then('the todo list contains {int} item', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count, 'todo list should have ' + count + ' items');
});

/**
 * @planks("the todo list has {int} items")
 */
Then('the todo list has {int} items', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  // Count only visible items (non-editing, non-completed that are shown)
  assert.strictEqual(items.length, count, 'todo list should have ' + count + ' items');
});

/**
 * @planks("the new todo has title {string}")
 */
Then('the new todo has title {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'todo list should have items');
  const lastItem = items[items.length - 1];
  const label = lastItem.querySelector('label');
  assert.strictEqual(label.textContent, title, 'new todo title should match');
});

/**
 * @planks("the new todo is not completed")
 */
Then('the new todo is not completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'todo list should have items');
  const lastItem = items[items.length - 1];
  assert.ok(!lastItem.classList.contains('completed'), 'new todo should not be completed');
});

/**
 * @planks("{string} is cleared")
 */
Then('{string} is cleared', function (selector) {
  const el = this.document.querySelector(selector);
  assert.ok(el, 'element should exist: ' + selector);
  assert.strictEqual(el.value, '', selector + ' should be cleared');
});

/**
 * @planks("the todo list is empty")
 */
Then('the todo list is empty', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0, 'todo list should be empty');
});

/**
 * @planks("all todos are completed")
 */
Then('all todos are completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'todo list should have items');
  items.forEach(function (li) {
    assert.ok(li.classList.contains('completed'), 'each todo should be completed');
  });
});

/**
 * @planks("{string} is checked")
 */
Then('{string} is checked', function (selector) {
  const el = this.document.querySelector(selector);
  assert.ok(el, 'element should exist: ' + selector);
  assert.strictEqual(el.checked, true, selector + ' should be checked');
});

/**
 * @planks("{string} is not checked")
 */
Then('{string} is not checked', function (selector) {
  const el = this.document.querySelector(selector);
  assert.ok(el, 'element should exist: ' + selector);
  assert.strictEqual(el.checked, false, selector + ' should not be checked');
});

/**
 * @planks("the item {string} has class {string}")
 */
Then('the item {string} has class {string}', function (title, className) {
  const items = this.document.querySelectorAll('.todo-list li');
  let found = false;
  items.forEach(function (li) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) {
      assert.ok(li.classList.contains(className), 'item should have class ' + className);
      found = true;
    }
  });
  assert.ok(found, 'item should exist: ' + title);
});

/**
 * @planks("the item {string} does not have class {string}")
 */
Then('the item {string} does not have class {string}', function (title, className) {
  const items = this.document.querySelectorAll('.todo-list li');
  let found = false;
  items.forEach(function (li) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) {
      assert.ok(!li.classList.contains(className), 'item should not have class ' + className);
      found = true;
    }
  });
  // Item may have been renamed; check that no item has the class
  if (!found) {
    items.forEach(function (li) {
      assert.ok(!li.classList.contains(className), 'no item should have class ' + className);
    });
  }
});

/**
 * @planks("the item {string} has a {string} button")
 */
Then('the item {string} has a {string} button', function (title, selector) {
  const items = this.document.querySelectorAll('.todo-list li');
  let found = false;
  items.forEach(function (li) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) {
      const btn = li.querySelector(selector);
      assert.ok(btn, 'button should exist: ' + selector);
      found = true;
    }
  });
  assert.ok(found, 'item should exist: ' + title);
});

/**
 * @planks("the item {string} is renamed to {string}")
 */
Then('the item {string} is renamed to {string}', function (oldTitle, newTitle) {
  const items = this.document.querySelectorAll('.todo-list li');
  let found = false;
  items.forEach(function (li) {
    const label = li.querySelector('label');
    if (label && label.textContent === newTitle) {
      // Verify the old title no longer exists as a label
      found = true;
    }
  });
  assert.ok(found, 'item should be renamed to: ' + newTitle);
});

/**
 * @planks("the item {string} has title {string}")
 */
Then('the item {string} has title {string}', function (title, expectedTitle) {
  const items = this.document.querySelectorAll('.todo-list li');
  let found = false;
  items.forEach(function (li) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) {
      found = true;
    }
  });
  assert.ok(found, 'item should have title: ' + title);
});

/**
 * @planks("{string} shows {string}")
 */
Then('{string} shows {string}', function (selector, expectedText) {
  const el = this.document.querySelector(selector);
  assert.ok(el, 'element should exist: ' + selector);
  const text = el.textContent.trim();
  assert.strictEqual(text, expectedText, selector + ' should show "' + expectedText + '"');
});

/**
 * @planks("the todo list has {int} item")
 */
Then('the todo list has {int} item', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count, 'todo list should have ' + count + ' items');
});

/**
 * @planks("the remaining todo has title {string}")
 */
Then('the remaining todo has title {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'todo list should have items');
  var label = items[0].querySelector('label');
  assert.strictEqual(label.textContent, title, 'remaining todo title should match');
});

/**
 * @planks("the item {string} is not completed")
 */
Then('the item {string} is not completed', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  var found = false;
  items.forEach(function (li) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) {
      assert.ok(!li.classList.contains('completed'), 'item should not be completed');
      found = true;
    }
  });
  assert.ok(found, 'item should exist: ' + title);
});

/**
 * @planks("the item {string} is completed")
 */
Then('the item {string} is completed', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  var found = false;
  items.forEach(function (li) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) {
      assert.ok(li.classList.contains('completed'), 'item should be completed');
      found = true;
    }
  });
  assert.ok(found, 'item should exist: ' + title);
});

/**
 * @planks("localStorage has a key {string}")
 */
Then('localStorage has a key {string}', function (key) {
  const value = this.localStorage.getItem(key);
  assert.ok(value !== null, 'localStorage should have key: ' + key);
});

/**
 * @planks("the todo list shows {int} items")
 */
Then('the todo list shows {int} items', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count, 'todo list should show ' + count + ' items');
});

/**
 * @planks("the todo list shows {int} item")
 */
Then('the todo list shows {int} item', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count, 'todo list should show ' + count + ' items');
